<script setup lang="ts">
import {ref} from 'vue';import {useRoute} from 'vue-router';import {useWallet} from '../stores/store';const isDep=useRoute().path.includes('deposit');const amount=ref(10000),provider=ref('M-Pesa'),phone=ref('+255');const w=useWallet();function go(){if(isDep){ if(amount.value>w.dailyLimit)return alert('Daily deposit limit / Kikomo cha siku'); w.add(amount.value,'deposit',provider.value+' (mock)')}else{ if(amount.value<1000)return alert('Min TZS 1,000'); if(amount.value>w.balance)return alert('Balance'); w.add(-amount.value,'withdraw',provider.value+' (mock)')} alert('Sandbox completed')};
</script>
<template><h2>{{isDep?'Deposit / Weka Pesa':'Withdraw / Toa Pesa'}}</h2><div class="card"><h3>Rules BEFORE you deposit / Kanuni KABLA ya kuweka pesa</h3><ul><li>KYC first / Thibitisha utambulisho kwanza (ID).</li><li>Processing: 1–24h real, instant in sandbox / Muda: saa 1–24.</li><li>Min TZS 1,000 · Max TZS 5,000,000 per transaction.</li><li>Wagering (x5) applies to BONUS only / inatumika kwa bonasi pekee.</li><li>Your own deposits & winnings are NEVER withheld for undisclosed reasons / Pesa yako na ushindi wako hautazuiliwa kwa sababu zisizotangazwa.</li></ul></div><select v-model="provider"><option>M-Pesa</option><option>Tigo Pesa</option><option>Airtel Money</option><option>HaloPesa</option></select><input v-model="phone"/><input type="number" v-model.number="amount"/><button @click="go">{{isDep?'Deposit (mock)':'Withdraw (mock)'}}</button></template>
